  | StD, S0 => mk S0 DL StA
  | StD, S1 => mk S0 DR StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1LC_1LA1RB_1LA1LD_0LA0RC : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1LC_1LA1RB_1LA1LD_0LA0RC pins_0RB1LC_1LA1RB_1LA1LD_0LA0RC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1LC_1LA1RB_1LA1LD_0LA0RC : Fam := mkFam 2 [[S0;S1;S1];[S1;S1;S1]] [] [[S1]] Binary 1 [mkFill 1 [0;1] 0 [] 0] StA S0 false [].
Local Notation FAM := fam_0RB1LC_1LA1RB_1LA1LD_0LA0RC.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LC_1LA1RB_1LA1LD_0LA0RC : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) 0 5, [RB (SWin 5)])].
Local Notation lad := lad_0RB1LC_1LA1RB_1LA1LD_0LA0RC.

Definition rules_0RB1LC_1LA1RB_1LA1LD_0LA0RC : list LRule := map fst lad.
Local Notation rules := rules_0RB1LC_1LA1RB_1LA1LD_0LA0RC.

Lemma ladder_ok_0RB1LC_1LA1RB_1LA1LD_0LA0RC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LC_1LA1RB_1LA1LD_0LA0RC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LC_1LA1RB_1LA1LD_0LA0RC. Qed.

