(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB1LC_1LA1RB_1LA1LD_0RA0LA : NeverQuasiHaltsTr tm_0RB1LC_1LA1RB_1LA1LD_0RA0LA.
Proof.
  apply (boardph_neverqhtr tm_0RB1LC_1LA1RB_1LA1LD_0RA0LA pins_0RB1LC_1LA1RB_1LA1LD_0RA0LA FAM 1
                           iarm_0RB1LC_1LA1RB_1LA1LD_0RA0LA 1 1
                           farm_0RB1LC_1LA1RB_1LA1LD_0RA0LA 1 1
                           fm1_0RB1LC_1LA1RB_1LA1LD_0RA0LA fm2_0RB1LC_1LA1RB_1LA1LD_0RA0LA 0 vis_0RB1LC_1LA1RB_1LA1LD_0RA0LA
                           [0] 0 15).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
