Definition iarm_0RB1LC_1LA1RB_1LB1LD____0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LC_1LA1RB_1LB1LD____0LA
  | 0, 1 => iarm0_1_0RB1LC_1LA1RB_1LB1LD____0LA
  | _, _ => iarm0_0_0RB1LC_1LA1RB_1LB1LD____0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1LC_1LA1RB_1LB1LD____0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1]))
