  | 0, 0 => iarm0_0_0RB1LC_1LA1RB_1LD0RA_1RB0LA
  | 0, 1 => iarm0_1_0RB1LC_1LA1RB_1LD0RA_1RB0LA
  | _, _ => iarm0_0_0RB1LC_1LA1RB_1LD0RA_1RB0LA   (* unreachable: only d < b-1 and r < N0 + st *)
