Lemma farm_lhs_0RB1LD_1LC1RB_1LA1LA_0LC0RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_0RB1LD_1LC1RB_1LA1LA_0LC0RA r ph)
