Proof. vm_compute. reflexivity. Qed.

Definition farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S0;S1;S1;S1]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S1] [S1;S0;S1] 1 0 [S1;S1;S1;S1;S1])) 6 10.
Definition ch_farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 4);RB (SCycL 3 0);RB (SWin 3)].
Lemma ok_farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC :
  check_arm tm true true rules farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC
            ch_farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_0RB1LD_1LC1RB_1RA1LA_1RA0LC (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_0RB1LD_1LC1RB_1RA1LA_1RA0LC
  | 1, 1 => farm1_1_0RB1LD_1LC1RB_1RA1LA_1RA0LC
  | _, _ => farm1_0_0RB1LD_1LC1RB_1RA1LA_1RA0LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB1LD_1LC1RB_1RA1LA_1RA0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 1 | _, _ => 0 end.
Definition fm2_0RB1LD_1LC1RB_1RA1LA_1RA0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_0RB1LD_1LC1RB_1RA1LA_1RA0LC (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => [SWin 3;SCycR 3;SWinR 8]
  | 1, (StB, S0) => [SWin 3;SCycR 3;SWinR 6]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 3;SCycR 3;SWin 5;SWinR 7;SCycL 3 0;SWinL 6]
  | 1, (StC, S1) => [SWin 3;SCycR 3;SWinR 7]
  | 1, (StD, S0) => [SWin 3;SCycR 3;SWin 5;SWinR 7;SCycL 3 0;SWin 3]
  | 1, (StD, S1) => [SWin 3;SCycR 3;SWinR 9]
  | _, _ => []
  end.

