    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LD_1LC1RB_1RA1LA_1RA0LC.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_0RB1LD_1LC1RB_1RA1LA_1RA0LC.
  - lia.
  - exact iarm_sound_0RB1LD_1LC1RB_1RA1LA_1RA0LC.
  - exact iarm_lhs_0RB1LD_1LC1RB_1RA1LA_1RA0LC.
